oxy_webhelp_navlinks = {"arch_prepare_azure_arch_loc-d39536e8194":{"topics":[{"title":"Azure archival locations with immutable storage","shortdesc":"<p class=\"shortdesc\">Azure archival locations with immutable storage protect data from being modified or         deleted from archives. Rubrik CDM 9.1 and later use blob-level immutability by default.         Container-level immutability is available only for clusters running CDM versions earlier         than 9.1.<\/p>","href":"archival\/azr_immutable_archival_locations.html","attributes":{"data-id":"azr_immutable_archival_locations"},"menu":{"hasChildren":false},"tocID":"azr_immutable_archival_locations-d39536e8205","next":"azr_immutable_archival_locations-d39536e8205"},{"title":"Access types for Azure archival locations","shortdesc":"<p class=\"shortdesc\">You can configure Azure archival locations with owner access or reader access,         depending on whether the connected Rubrik cluster writes archives or only reads         them.<\/p>","href":"archival\/arch_azure_access_types.html","attributes":{"data-id":"arch_azure_access_types"},"menu":{"hasChildren":false},"tocID":"arch_azure_access_types-d39536e8238","topics":[]},{"title":"Encryption options for Azure archival locations","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports RSA key and Azure Key Vault encryption to protect Azure         archival data at rest. Data in transit is always protected by TLS, regardless of the         encryption configuration.<\/p>","href":"archival\/arch_azure_encryption_options.html","attributes":{"data-id":"arch_azure_encryption_options"},"menu":{"hasChildren":false},"tocID":"arch_azure_encryption_options-d39536e8249","topics":[]},{"title":"Archive preparation in Azure","shortdesc":"<p class=\"shortdesc\">Before archiving data from a Rubrik cluster to Azure, prepare your Azure storage         account, storage container, permissions, and Service Principal identities.<\/p>","href":"archival\/archive_preparation_in_azure.html","attributes":{"data-id":"archive_preparation_in_azure"},"menu":{"hasChildren":false},"tocID":"archive_preparation_in_azure-d39536e8262","next":"archive_preparation_in_azure-d39536e8262"}]}};